const people = [["Pieter", "Bakker"], ["Joost", "van der Berg"], ["Anna", "de Vries"]];
const naiveOrder = [...people].sort((a, b) => a[1].toLowerCase().localeCompare(b[1].toLowerCase()));
console.log(naiveOrder.map((p) => p[1]));

const PARTICLES = new Set(["van", "der", "de", "von", "del", "la"]);
function catalogKey(surname) {
  const words = surname.split(" ");
  while (words.length && PARTICLES.has(words[0].toLowerCase())) words.shift();
  return words.join(" ").toLowerCase();
}
const catalogOrder = [...people].sort((a, b) => catalogKey(a[1]).localeCompare(catalogKey(b[1])));
console.log(catalogOrder.map((p) => p[1]));
console.log(JSON.stringify(naiveOrder) === JSON.stringify(catalogOrder));
